/** Back / Chevron-left icon */
export function ChevronLeftIcon({
  size = 24,
  color = "#fff",
  ...props
}: IconProps) {
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24" fill="none" {...props}>
      <Path
        fillRule="evenodd"
        clipRule="evenodd"
        d="M15.5303 4.46967C15.8232 4.76256 15.8232 5.23744 15.5303 5.53033L9.06066 12L15.5303 18.4697C15.8232 18.7626 15.8232 19.2374 15.5303 19.5303C15.2374 19.8232 14.7626 19.8232 14.4697 19.5303L7.46967 12.5303C7.17678 12.2374 7.17678 11.7626 7.46967 11.4697L14.4697 4.46967C14.7626 4.17678 15.2374 4.17678 15.5303 4.46967Z"
        fill={color}
      />
    </Svg>
  );
}

